package net.officefloor.hq.app.session;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A user's locale: how the screen shows them figures. It is kept per user, across every sheet. */
@Entity
@Table(name = "user_locale")
public class UserLocale {

    /** The locale a user has until they choose one. */
    public static final String DEFAULT = "en";

    @Id
    @Column(name = "user_name", nullable = false)
    private String user;

    @Column(name = "locale", nullable = false)
    private String locale;

    protected UserLocale() {
    }

    public UserLocale(String user, String locale) {
        this.user = user;
        this.locale = locale;
    }

    public String getUser() {
        return user;
    }

    public String getLocale() {
        return locale;
    }

    public void setLocale(String locale) {
        this.locale = locale;
    }
}
package net.officefloor.hq.app.session;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Reads and saves each user's locale. Choosing a locale writes no audit line. */
@Service
public class UserLocaleService {

    private final UserLocaleRepository locales;

    public UserLocaleService(UserLocaleRepository locales) {
        this.locales = locales;
    }

    @Transactional(readOnly = true)
    public String localeOf(String user) {
        return locales.findById(user).map(UserLocale::getLocale).orElse(UserLocale.DEFAULT);
    }

    @Transactional
    public String setLocale(String user, String locale) {
        locales.findById(user).ifPresentOrElse(
                l -> l.setLocale(locale),
                () -> locales.save(new UserLocale(user, locale)));
        return locale;
    }
}
package net.officefloor.hq.app.session;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

/**
 * Sign-in by name; there is no password. The front end sends the name back as {@code X-User}. Signing in
 * answers with the user's saved locale, which they may change.
 */
@RestController
@Validated
public class SessionController {

    public record SignIn(@NotBlank @Size(max = 100) String name) {
    }

    public record SignedIn(String name, String locale) {
    }

    public record LocaleForm(@NotBlank @Pattern(regexp = "en|de") String locale) {
    }

    public record LocaleView(String locale) {
    }

    private final UserLocaleService locales;

    public SessionController(UserLocaleService locales) {
        this.locales = locales;
    }

    @PostMapping("/api/signin")
    public SignedIn signIn(@Valid @RequestBody SignIn request) {
        String name = request.name().trim();
        return new SignedIn(name, locales.localeOf(name));
    }

    @PutMapping("/api/me/locale")
    public LocaleView setLocale(
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody LocaleForm form) {
        return new LocaleView(locales.setLocale(user.trim(), form.locale()));
    }
}

